# Execution guard between the drafter and the one node that can spend.
# The drafter holds no tools; this transform is the last PURE check before
# the airlocked place_bid: bound the proposal, carry the currency forward,
# and refuse to arm execution on an empty or oversized draft.
d = input.get("draft") if isinstance(input, dict) else None
v = input.get("pick") if isinstance(input, dict) else None
d = d if isinstance(d, dict) else {}
v = v if isinstance(v, dict) else {}
proposal = str(d.get("proposal") or d.get("text") or "")
amount = d.get("amount")
amount_ok = isinstance(amount, (int, float)) and not isinstance(amount, bool) and amount > 0
problems = []
if not v.get("ready"):
    problems.append("validate_pick did not clear the project")
if len(proposal) < 80:
    problems.append("proposal under 80 chars")
if len(proposal) > 1500:
    problems.append("proposal over 1500 chars")
if not amount_ok:
    problems.append("no positive numeric bid amount drafted")
if not v.get("currency"):
    problems.append("no currency to denominate the bid")
output = {
    "execution_ready": len(problems) == 0,
    "problems": problems,
    "project_id": v.get("project_id"),
    "amount": amount if amount_ok else None,
    "currency": v.get("currency"),
    "proposal_chars": len(proposal),
}

# After the airlock: reconcile what was PLANNED against what the bid agent
# REPORTS, so a mismatch is a first-class outcome instead of a silent success.
p = input.get("plan") if isinstance(input, dict) else None
b = input.get("bid") if isinstance(input, dict) else None
p = p if isinstance(p, dict) else {}
b = b if isinstance(b, dict) else {}
placed = b.get("bid_id") or b.get("placed")
planned_amount = p.get("amount")
placed_amount = b.get("amount")
pn = isinstance(planned_amount, (int, float)) and not isinstance(planned_amount, bool)
bn = isinstance(placed_amount, (int, float)) and not isinstance(placed_amount, bool)
if not p.get("execution_ready"):
    status = "skipped_by_guard"
elif not placed:
    status = "not_placed"
elif not (pn and bn) or placed_amount != planned_amount:
    status = "amount_mismatch"
else:
    status = "placed"
output = {
    "status": status,
    "planned_amount": planned_amount,
    "placed_amount": placed_amount,
    "currency": p.get("currency"),
    "project_id": p.get("project_id"),
}

